"""Measure covariate support for a blind codicological mate comparison."""

from collections import Counter, defaultdict
import csv
from hashlib import sha256
from html import unescape
from itertools import combinations
import json
from pathlib import Path
import re
from statistics import median
from string import ascii_uppercase


WORK = Path(__file__).resolve().parent
PIN = WORK.parent / "voynich-swarm" / "data" / "raw" / "ZL3b-n.txt"
PAGE_ID = re.compile(r"^(f\d+)([rv])\d*$")
HEADER = re.compile(r"^<(f\d+)[rv]\d*>\s+<!\s+(.*)>", re.M)
FOLIO_PAIR = re.compile(r"Folio\s+(\d+)\s*,\s*together with folio\s+(\d+)", re.I)


def manifest(path):
    return sha256(path.read_bytes()).hexdigest()


def csv_rows(name):
    with (WORK / name).open() as stream:
        return list(csv.DictReader(stream))


def physical_map():
    observed = defaultdict(set)
    for leaf, header in HEADER.findall(PIN.read_text(encoding="utf-8-sig")):
        fields = dict(re.findall(r"\$([A-Z])=([^\s]+)", header))
        if "Q" in fields and "B" in fields:
            observed[leaf].add((fields["Q"], fields["B"]))
    assert all(len(values) == 1 for values in observed.values())
    return {leaf: next(iter(values)) for leaf, values in observed.items()}


def number(leaf):
    return int(leaf[1:])


def pair_code(left, right):
    return tuple(sorted((left, right), key=number))


def groups_to_pairs(metadata, allowed):
    groups = defaultdict(list)
    for leaf in sorted(allowed, key=number):
        groups[metadata[leaf]].append(leaf)
    assert all(len(group) <= 2 for group in groups.values())
    return {pair_code(*group) for group in groups.values() if len(group) == 2}


def verify_described_collation(metadata, physical_mates):
    listed = set()
    mismatches = []
    page_hashes = {}
    for path in sorted(WORK.glob("quire-*.html")):
        code = ascii_uppercase[int(path.stem.rsplit("-", 1)[1]) - 1]
        text = unescape(re.sub("<[^>]*>", " ", path.read_text(encoding="utf-8", errors="replace")))
        for numbers in FOLIO_PAIR.findall(" ".join(text.split())):
            leaves = pair_code(*(f"f{value}" for value in numbers))
            if leaves in physical_mates and all(metadata[leaf][0] == code for leaf in leaves):
                listed.add(leaves)
            elif all(leaf in metadata for leaf in leaves):
                mismatches.append([code, *leaves])
        page_hashes[path.name] = manifest(path)
    return {
        "explicit_text_pairs_agree": [list(pair) for pair in sorted(listed, key=lambda value: tuple(map(number, value)))],
        "explicit_text_conflicts": sorted({tuple(row) for row in mismatches}),
        "description_sha256": page_hashes,
    }


def verify_archive_inventory(metadata, physical_mates):
    inventory = []
    for row in csv_rows("bifolio_mapping_comparison.csv"):
        if row["in_evt"] != "True":
            continue
        quire, values = row["pair"].split(":")
        left, right = pair_code(*(f"f{value}" for value in values.split("-")))
        inventory.append((quire, left, right))
    comparable = {
        (left, right) for quire, left, right in inventory
        if left in metadata and right in metadata and metadata[left][0] == metadata[right][0] == quire
    }
    return {
        "evt_mapped_relationships_including_missing": len(inventory),
        "common_with_pinned_canonical_map": len(comparable & physical_mates),
        "inventory_pairs_disagreeing_given_two_canonical_leaves": sorted(comparable - physical_mates),
        "canonical_pairs_absent_from_inventory": sorted(physical_mates - comparable),
    }


def compare_counts(metadata, physical_mates, available, quality=None):
    candidates = defaultdict(list)
    for left, right in combinations(sorted(available, key=number), 2):
        if metadata[left][0] != metadata[right][0] or (left, right) in physical_mates:
            continue
        signature = tuple(sorted((quality[left], quality[right]))) if quality else ()
        key = (metadata[left][0], number(right) - number(left), signature)
        candidates[key].append((left, right))
    supported = []
    unavailable = []
    eligible = physical_mates.intersection(combinations(sorted(available, key=number), 2))
    for left, right in sorted(eligible, key=lambda pair: tuple(map(number, pair))):
        quire = metadata[left][0]
        signature = tuple(sorted((quality[left], quality[right]))) if quality else ()
        key = (quire, number(right) - number(left), signature)
        controls = candidates.get(key, [])
        if controls:
            supported.append({
                "quire": quire,
                "mate": [left, right],
                "quality_signature": signature,
                "nonmates": controls,
                "disjoint_nonmates": sum(not ({a, b} & {left, right}) for a, b in controls),
            })
        else:
            unavailable.append([left, right])
    return {
        "eligible_leaves": len(available),
        "eligible_mates": len(eligible),
        "informative_mates": len(supported),
        "informative_quires": len({row["quire"] for row in supported}),
        "informative_mates_with_disjoint_control": sum(row["disjoint_nonmates"] > 0 for row in supported),
        "informative_quires_with_disjoint_control": len({
            row["quire"] for row in supported if row["disjoint_nonmates"] > 0
        }),
        "mate_rows": supported,
        "no_exact_control": unavailable,
    }


def scan_report(scan, metadata, physical_mates):
    archive = csv_rows(f"{scan}_leaf.csv")
    archive_leaves = {row["leaf"] for row in archive}
    assert all(row["quire"] == metadata[row["leaf"]][0] for row in archive)
    archive_map = {row["leaf"]: (row["quire"], row["bifolio"]) for row in archive}
    assert groups_to_pairs(archive_map, archive_leaves) == groups_to_pairs(metadata, archive_leaves)
    registration = [row for row in csv_rows("registration_qc.csv") if row["source"] == f"{scan}_nominal"]
    feature_rows = {row["page"]: row for row in csv_rows(f"{scan}_page.csv")}
    passes = {row["page"]: row for row in registration if row["passed"] == "True"}
    assert set(passes) == set(feature_rows)
    error_midpoint = median(float(row["heldout_p90_error_px"]) for row in passes.values())
    quality_sides = defaultdict(dict)
    crop_counts = defaultdict(dict)
    for page, row in passes.items():
        leaf, side = PAGE_ID.fullmatch(page).groups()
        quality_sides[leaf][side] = int(float(row["heldout_p90_error_px"]) > error_midpoint)
        crop_counts[leaf][side] = int(float(feature_rows[page]["n_valid_crops"]))
    assert set(quality_sides) == archive_leaves
    two_sides = {leaf for leaf, sides in quality_sides.items() if len(sides) == 2}
    quality = {leaf: tuple(quality_sides[leaf][side] for side in ("r", "v")) for leaf in two_sides}
    high_confidence = {leaf for leaf in two_sides if min(crop_counts[leaf].values()) >= 20}
    coverage = Counter((PAGE_ID.fullmatch(row["page"])[2], row["passed"]) for row in registration)
    failure_reasons = Counter(row["failure_reason"] for row in registration if row["passed"] != "True")
    return {
        "registration_by_side": {
            side: {"passed": coverage[side, "True"], "failed": coverage[side, "False"]}
            for side in ("r", "v")
        },
        "registration_failures": dict(failure_reasons),
        "median_registration_p90_px": error_midpoint,
        "one_or_two_sides": compare_counts(metadata, physical_mates, archive_leaves),
        "both_sides": compare_counts(metadata, physical_mates, two_sides),
        "both_and_matched_error_tier": compare_counts(metadata, physical_mates, two_sides, quality),
        "source_min_20_crops_each_side": compare_counts(metadata, physical_mates, high_confidence),
        "source_min_20_crops_each_side_and_error_tier": compare_counts(
            metadata, physical_mates, high_confidence, quality
        ),
    }, quality


def main():
    metadata = physical_map()
    mates = groups_to_pairs(metadata, set(metadata))
    baseline = compare_counts(metadata, mates, set(metadata))
    results, profiles = {}, {}
    for scan in ("voyager", "yale"):
        results[scan], profiles[scan] = scan_report(scan, metadata, mates)
    common = set(profiles["yale"]) & set(profiles["voyager"])
    signed = {leaf: (profiles["yale"][leaf], profiles["voyager"][leaf]) for leaf in common}
    print(json.dumps({
        "codicology": {
            "canonical_transliteration_sha256": manifest(PIN),
            "canonical_leaves": len(metadata),
            "published_descriptions": verify_described_collation(metadata, mates),
            "archived_evt_inventory": verify_archive_inventory(metadata, mates),
            "all_canonical_before_registration": baseline,
        },
        "scan_results": results,
        "common_two_sides_both_scan_error_tiers": compare_counts(metadata, mates, common, signed),
        "input_sha256": {path.name: manifest(path) for path in sorted(WORK.glob("*.csv"))},
    }, indent=2))


if __name__ == "__main__":
    main()
